로드할 PPTX 수', 'import.max_file_mb': 'PPTX 파일당 최대 MB', 'import.retention_days': 'Import 원본 보관일', 'confluence.enabled': 'Confluence 자동 수집 사용', 'confluence.base_url': 'Confluence Base URL', 'confluence.auth_mode': '인증 방식', 'confluence.username': 'Service Account', 'confluence.password': 'Service Account 비밀번호', 'confluence.include_spaces': '포함 Space (쉼표 구분)', 'confluence.exclude_spaces': '제외 Space (쉼표 구분)', 'confluence.sync_interval_minutes': '자동 수집 주기(분)', 'confluence.ai_enabled': 'Confluence AI 분류·요약 사용', 'confluence.minimum_candidate_score': '자동 후보 최소 점수', 'confluence.ai_review_min_score': 'AI 검토 최소 점수', 'confluence.analyze_body': '후보 문서 본문 분석', 'confluence.lookback_days': '첫 수집 조회 기간(일)', 'confluence.batch_size': 'API 페이지 크기', 'confluence.include_blogs': 'Blog Post 포함', 'confluence.auto_map_email_localpart': '이메일 @ 앞부분 자동 매핑', 'confluence.auto_map_username': '로그인 아이디 자동 매핑', 'confluence.work_keywords': '업무성 키워드', 'confluence.personal_space_prefixes': '개인 Space 접두사', 'confluence.score_project_space': '포함 Space 점수', 'confluence.score_creator': '본인 작성 점수', 'confluence.score_modifier': '본인 최종 수정 점수', 'confluence.score_work_keyword': '업무 키워드 점수', 'confluence.score_meeting': '회의 문서 점수', 'confluence.score_notice': '공지 문서 점수', 'confluence.score_leave': '휴가 문서 점수', 'confluence.score_personal_space': '개인 Space 점수', 'mail.enabled': '주간보고 메일 발송 사용', 'mail.host': 'SMTP 호스트', 'mail.port': 'SMTP 포트', 'mail.security': '연결 보안', 'mail.username': 'SMTP 계정 (선택)', 'mail.password': 'SMTP 비밀번호', 'mail.from': '보내는 주소', 'mail.from_name': '보내는 사람 이름', 'mail.timeout_seconds': '발송 제한시간(초)', 'mail.max_attempts': '재시도 횟수', 'itsm.enabled': 'ITSM 연동 사용', 'itsm.lookup_url': '조회 주소 (API)', 'itsm.link_url': '이동 주소 (포털)', 'itsm.query_param': 'SR 번호 파라미터 이름', 'itsm.title_path': '제목 JSON 경로', 'itsm.title_regex': '제목 추출 정규식 (HTML용)', 'itsm.id_pattern': 'SR 번호 형식 정규식', 'itsm.auth_header': '인증 헤더 이름', 'itsm.auth_token': '인증 토큰', 'itsm.label': '화면 표기 이름', 'itsm.timeout_seconds': '조회 제한시간(초)' }

// The queue a row came from, in the operator's words. The kind is what
// separates "the relay is refusing everybody" from "one leader's reminder".
const mailDeliveryKindLabels: Record<MailDeliveryKind, string> = { REPORT: '제출 메일', TEAM_REMINDER: '작성 권고', SCHEDULE_REMINDER: '마감 알림' }
const mailDeliveryStatusLabels: Record<MailDeliveryStatus, string> = { QUEUED: '대기', SENT: '발송', FAILED: '실패' }
function SettingsTab({ notify, changed }: { notify: (message: string, kind?: 'success' | 'error') => void; changed: () => Promise<void> }) {
  const [settings, setSettings] = useState<Setting[]>()
  const [values, setValues] = useState<Record<string, string>>({})
  const [embedding, setEmbedding] = useState<EmbeddingStatus>()
  // Where the secret encryption key lives decides whether a lost state volume
  // costs the secret settings. The README tells operators this matters; until
  // now the only place that said which mode a deployment was in was one line of
  // the boot log, gone by the time anybody asks.
  const [encryption, setEncryption] = useState<EncryptionStatus>()
  const load = () => api<Setting[]>('/api/v1/admin/settings').then(data => { setSettings(data); setValues(Object.fromEntries(data.map(item => [item.key, item.value ?? '']))) })
  // Coverage is what tells an operator whether semantic search can answer at
  // all, so it is loaded next to the settings that control it.
  const loadEmbedding = () => api<EmbeddingStatus>('/api/v1/admin/embeddings').then(setEmbedding).catch(() => setEmbedding(undefined))
  const loadEncryption = () => api<EncryptionStatus>('/api/v1/admin/encryption').then(setEncryption).catch(() => setEncryption(undefined))
  useEffect(() => { load(); loadEmbedding(); loadEncryption() }, [])
  // remaining is absent when the backlog count itself failed: saying "남은
  // 항목이 없습니다" on behalf of a count nobody got an answer from is what
  // stops an operator from pressing the button again.
  const rebuildEmbeddings = async () => { try { const result = await api<{ embedded: number, remaining?: number, remainingUnread?: boolean }>('/api/v1/admin/embeddings/rebuild',
      // Up to 6,400 items against a gateway with its own per-request timeout;
      // the default bound is for requests that should be instant.
      { method: 'POST', body: '{}', signal: AbortSignal.timeout(UPLOAD_TIMEOUT_MS) }); await loadEmbedding(); notify(result.remainingUnread ? `임베딩 ${result.embedded.toLocaleString()}건을 생성했습니다. 남은 건수를 읽지 못했습니다 — 백그라운드 작업자가 이어서 처리합니다.` : (result.remaining ?? 0) > 0 ? `임베딩 ${result.embedded.toLocaleString()}건을 생성했습니다. ${(result.remaining ?? 0).toLocaleString()}건이 남았고 백그라운드 작업자가 이어서 처리합니다.` : `임베딩 ${result.embedded.toLocaleString()}건을 생성했습니다. 남은 항목이 없습니다.`) } catch (error) { notify(errorText(error, '임베딩을 생성할 수 없습니다.'), 'error') } }
  // Saving a blank secret means "keep what is there", so a masked form cannot
  // wipe a password by being submitted. Removing one therefore needs its own
  // verb: an integration switched off, or a secret this deployment's key can no
  // longer read, otherwise stayed in the table with nothing to be done about it
  // except typing a password nobody wants stored.
  const clearSecret = async (key: string) => {
    if (!confirm(`${labels[key] ?? key} 값을 지우시겠습니까? 해당 기능은 값을 다시 입력할 때까지 동작하지 않습니다.`)) return
    try {
      await del(`/api/v1/admin/settings/${encodeURIComponent(key)}`)
      setValues(current => ({ ...current, [key]: '' }))
      // The row and the card read the same fact from two endpoints. Reloading
      // only the settings left the warning above still naming a key that was
      // no longer there, which is the screen disagreeing with itself.
      await Promise.all([load(), loadEncryption()])
      notify(`${labels[key] ?? key} 값을 지웠습니다.`)
    } catch (error) {
      notify(errorText(error, '설정을 지울 수 없습니다.'), 'error')
    }
  }
  // A change the server refuses until its consequences are accepted comes back
  // as 409 with the explanation. Showing that text and asking is better than a
  // warning nobody reads next to a field they are not touching.
  const save = async (confirmed: string[] = []) => {
    try {
      await put('/api/v1/admin/settings', { settings: values, confirmed })
      await load(); await changed(); notify('서비스 설정을 저장했습니다.')
    } catch (error) {
      if (error instanceof APIError && error.code === 'WEEK_START_NEEDS_CONFIRMATION') {
        if (confirm(`${error.message}\n\n계속하시겠습니까?`)) { await save(['workflow.week_start']); return }
        notify('주차 시작 요일을 바꾸지 않았습니다.')
        return
      }
      notify(errorText(error, '설정을 저장할 수 없습니다.'), 'error')
    }
  }
  const testOIDC = async () => { try { await post('/api/v1/admin/settings/oidc/test'); notify('OIDC Discovery 연결에 성공했습니다.') } catch (error) { notify(errorText(error, 'OIDC 연결에 실패했습니다.'), 'error') } }
  const testAI = async () => { try { const result = await post<{ model: string; items: number }>('/api/v1/admin/settings/ai/test'); notify(`${result.model} AI 연결과 Structured Output 검증에 성공했습니다.`) } catch (error) { notify(errorText(error, 'AI 연결에 실패했습니다.'), 'error') } }
  // Sent to the administrator running the test, not to an address they type:
  // a test that can be pointed anywhere is a way to send mail from this server
  // to a stranger, and the question here is only whether the relay works.
  const [mailHealth, setMailHealth] = useState<MailHealth>()
  // Read once with the settings. It is a figure to glance at, not a live feed.
  useEffect(() => { api<MailHealth>('/api/v1/admin/mail/health').then(setMailHealth).catch(() => setMailHealth(undefined)) }, [])
  // The rows behind the figures — which reminder the relay refused, and why —
  // so a red number does not send the operator to the queue tables.
  const [mailDeliveries, setMailDeliveries] = useState<MailDeliveryList>()
  // The filter is the whole point of the table on a good week. 50 rows of a
  // morning's digests push the one refusal the figures above are counting off
  // the bottom, so the server narrows the window rather than the page and the
  // screen re-reads when either condition changes.
  const [mailKind, setMailKind] = useState<MailDeliveryKind | ''>('')
  const [mailStatus, setMailStatus] = useState<MailDeliveryStatus | ''>('')
  useEffect(() => {
    const query = new URLSearchParams()
    if (mailKind) query.set('kind', mailKind)
    if (mailStatus) query.set('status', mailStatus)
    const suffix = query.toString()
    api<MailDeliveryList>(`/api/v1/admin/mail/deliveries${suffix ? `?${suffix}` : ''}`).then(setMailDeliveries).catch(() => setMailDeliveries(undefined))
  }, [mailKind, mailStatus])
  const testMail = async () => { try { const result = await post<{ to: string }>('/api/v1/admin/settings/mail/test'); notify(`${result.to} 로 시험 메일을 보냈습니다.`) } catch (error) { notify(errorText(error, '메일 발송에 실패했습니다.'), 'error') } }
  const [itsmSample, setItsmSample] = useState('')
  // The administrator setting this up is debugging a URL template, a header and
  // a path into somebody else's JSON. A pass/fail would make that a guessing
  // game, so the answer carries the status code and what came back.
  const testITSM = async () => {
    try {
      const result = await post<{ ok: boolean; title?: string; url?: string; lookupUrl?: string; status?: number; snippet?: string; error?: string }>(
        '/api/v1/admin/settings/itsm/test', { id: itsmSample.trim() })
      if (result.ok) notify(`제목: ${result.title} · 이동 주소: ${result.url || '미설정'}`)
      else notify(`${result.error ?? '조회 실패'}${result.status ? ` (HTTP ${result.status})` : ''}${result.snippet ? ` · 응답: ${result.snippet.slice(0, 120)}` : ''}`, 'error')
    } catch (error) { notify(errorText(error, 'ITSM 조회 시험에 실패했습니다.'), 'error') }
  }
  const testConfluence = async () => { try { await post('/api/v1/admin/settings/confluence/test'); notify('Confluence 6.9.1 REST API 연결에 성공했습니다.') } catch (error) { notify(errorText(error, 'Confluence 연결에 실패했습니다.'), 'error') } }
  if (!settings) return <Spinner/>
  const groups = [{ title: '일반 · 워크플로', keys: ['service.name','service.notice','service.timezone','workflow.enabled','workflow.week_start','workflow.deadline_days','workflow.deadline_hour'] }, { title: '인증 · Keycloak OIDC', keys: ['auth.local_enabled','auth.session_hours','auth.max_login_attempts','auth.lockout_minutes','auth.max_login_attempts_per_ip','oidc.enabled','oidc.issuer_url','oidc.client_id','oidc.client_secret','oidc.redirect_url','oidc.scopes','oidc.username_claim','oidc.groups_claim','oidc.admin_group','oidc.auto_provision','oidc.auto_login'] }, { title: 'AI Gateway · 과거 자료 Import', keys: ['ai.enabled','ai.endpoint','ai.api_key','ai.model','ai.timeout_seconds','ai.max_input_chars','import.max_files','import.max_file_mb','import.retention_days'] }, { title: 'Confluence 6.9.1 자동화', keys: ['confluence.enabled','confluence.base_url','confluence.auth_mode','confluence.username','confluence.password','confluence.include_spaces','confluence.exclude_spaces','confluence.sync_interval_minutes','confluence.ai_enabled','confluence.minimum_candidate_score','confluence.ai_review_min_score','confluence.analyze_body','confluence.lookback_days','confluence.batch_size','confluence.include_blogs','confluence.auto_map_email_localpart','confluence.auto_map_username','confluence.work_keywords','confluence.personal_space_prefixes','confluence.score_project_space','confluence.score_creator','confluence.score_modifier','confluence.score_work_keyword','confluence.score_meeting','confluence.score_notice','confluence.score_leave','confluence.score_personal_space'] }, { title: '주간보고 메일 발송', keys: ['mail.enabled','mail.host','mail.port','mail.security','mail.username','mail.password','mail.from','mail.from_name','mail.timeout_seconds','mail.max_attempts'] }, { title: 'MCP SSO (OAuth)', keys: ['mcp.oauth.enabled','mcp.oauth.resource','mcp.oauth.audience','mcp.oauth.scopes'] }, { title: 'ITSM 연동', keys: ['itsm.enabled','itsm.lookup_url','itsm.link_url','itsm.query_param','itsm.title_path','itsm.title_regex','itsm.id_pattern','itsm.auth_header','itsm.auth_token','itsm.label','itsm.timeout_seconds'] }, { title: '화면 캡처 첨부', keys: ['attachment.max_per_report','attachment.max_file_mb'] }, { title: '기간 업무보고 집계', keys: ['rollup.merge_similarity','rollup.stall_weeks','rollup.persistent_issue_weeks','rollup.max_weeks'] }, { title: '보안 · 분석', keys: ['security.api_key_max_days','analytics.retention_days','audit.retention_days'] }, { title: '검색', keys: ['search.similarity_threshold','ai.embedding_enabled','ai.embedding_endpoint','ai.embedding_model','search.semantic_threshold'] }]
  const booleanKeys = ['workflow.enabled','auth.local_enabled','oidc.enabled','oidc.auto_provision','oidc.auto_login','ai.enabled','confluence.enabled','confluence.ai_enabled','confluence.analyze_body','confluence.include_blogs','confluence.auto_map_email_localpart','confluence.auto_map_username','ai.embedding_enabled','itsm.enabled','mcp.oauth.enabled']
  return <div className="settings-stack">
    {/* 이미 일어난 일이 먼저입니다. 아래 두 문장은 키를 잃으면 무슨 일이
        벌어지는지에 대한 경고인데, 그 일이 이미 벌어진 배포에도 그대로
        걸려 있었습니다. */}
    {encryption && encryption.unreadable && encryption.unreadable.length > 0 && <p className="capture-warning">
      저장된 비밀 설정 <strong>{encryption.unreadable.length}개</strong>를 지금 쓰는 암호화 키로 읽을 수 없습니다 — {encryption.unreadable.map((key, index) => <span key={key}>{index > 0 && ', '}<code>{key}</code></span>)}.
      키가 바뀌었거나 <code>{encryption.stateDirectory}</code> 볼륨이 예전 것이 아닙니다. 예전 키를 <code>WEEKLY_ENCRYPTION_KEY</code>로 되돌리거나, 각 설정을 다시 입력해 저장하십시오. 그때까지 해당 기능은 동작하지 않습니다.</p>}
    {encryption && (encryption.recoverable
      ? <p className="setting-help">비밀 설정 암호화 키: {encryption.keySource === 'environment'
          ? `WEEKLY_ENCRYPTION_KEY 환경변수. ${encryption.stateDirectory} 볼륨을 잃어도 저장된 비밀 설정 ${encryption.storedSecrets}개를 복구할 수 있습니다.`
          : `${encryption.stateDirectory} 볼륨의 instance.key. 아직 저장된 비밀 설정이 없어 지금은 잃을 것이 없습니다.`}</p>
      : <p className="capture-warning">비밀 설정 암호화 키가 <code>{encryption.stateDirectory}</code> 볼륨 안에만 있습니다. 이 볼륨을 잃으면 저장된 비밀 설정 <strong>{encryption.storedSecrets}개</strong>를 복구할 수 없습니다. <code>WEEKLY_ENCRYPTION_KEY</code>를 지정하고 재기동하면 키가 볼륨과 분리됩니다.</p>)}
    {groups.map(group => <Card key={group.title} title={group.title}>{group.title === '화면 캡처 첨부' && <p className="setting-help">PPTX 내보내기는 첨부 이미지를 만들어지는 파일에 담습니다. 실측하면 요청 하나가 쓰는 메모리는 <strong>첨부 총량의 약 3.5배</strong>입니다 — 캡처 20장 44.9MB를 내보낼 때 컨테이너가 78MiB에서 235MiB로 올라갔습니다. 이미지는 하나씩 읽어 담지만, 완성된 파일 자체를 메모리에 들고 응답하기 때문입니다. 따라서 상한은 <code>보고서당 최대 캡처 수 × 캡처 파일당 최대 MB × 3.5</code>이고, 동시에 내보내는 사람 수만큼 곱해집니다. 기본값 20장 × 10MB 라면 요청 하나가 <strong>약 700MB</strong>입니다. 컨테이너 메모리 한도를 이 값으로 잡으세요.</p>}{group.title.startsWith('일반') && <p className="setting-help">제출 마감은 <strong>주차 시작일 기준</strong>입니다. 기본값 7일 24시는 주차 시작일로부터 7일째 되는 날 자정, 즉 다음 주 첫날 0시입니다. 금요일 15시가 마감이고 주차가 월요일에 시작한다면 4일 15시로 설정하세요. 판정은 서비스 시간대를 사용합니다.</p>}{group.title.startsWith('인증') && <p className="setting-help">로그인 실패가 허용 횟수에 이르면 <strong>차단 시간</strong> 동안 그 계정의 로그인을 거부합니다. 실패 횟수에 따라 응답도 점점 느려집니다. <strong>IP당 제한은 기본으로 꺼져 있습니다.</strong> 사무실 NAT이나 Reverse Proxy 뒤에서는 여러 사람이 같은 주소로 보이므로, 남의 오타 때문에 한 층이 통째로 잠길 수 있습니다. 클라이언트 주소가 실제로 구분되는 망에서만 켜십시오.</p>}{group.title.startsWith('AI Gateway') && <p className="setting-help">OpenAI 호환 <code>/v1/chat/completions</code> Endpoint와 Structured Output(JSON Schema)을 지원하는 모델을 지정하세요. 사내 AI Gateway는 API Key를 비워 둘 수 있습니다.</p>}{group.title === '주간보고 메일 발송' && <p className="setting-help">주간보고를 <strong>제출할 때</strong> 작성자가 개인 설정에 저장한 주소로 발송합니다. 발송은 제출 트랜잭션 밖에서 이루어지므로 <strong>릴레이가 죽어 있어도 제출은 실패하지 않습니다</strong> — 밀린 발송은 큐에 남아 다시 시도되고, 작성자는 개인 설정에서 그 상태를 봅니다. 사내 릴레이가 포트 25에 인증 없이 열려 있는 경우가 흔하므로 보안 <strong>없음(평문)</strong>이 기본값입니다. 다만 <strong>계정을 쓰려면 STARTTLS나 TLS가 필요합니다</strong> — 평문 연결에는 비밀번호를 실어 보내지 않습니다.</p>}{group.title === '기간 업무보고 집계' && <p className="setting-help">월간·분기·반기·연간 보고를 만들 때 같은 업무로 묶을 <strong>제목 유사도</strong>와, 정체·이슈 지속으로 판정할 <strong>연속 주차 수</strong>입니다. 최대 주차 수는 한 번의 집계가 읽는 주차의 상한이며, 넘는 기간은 잘라서 집계하고 화면에 그 사실을 표시합니다.</p>}{group.title === 'MCP SSO (OAuth)' && <p className="setting-help">MCP 클라이언트(Claude Desktop, Cursor 등)가 개인 키 대신 <strong>Keycloak 로그인</strong>으로 연결합니다. 켜면 <code>/.well-known/oauth-protected-resource</code> 가 인증 서버(<code>Issuer URL</code>)를 알리고, 클라이언트는 그곳에서 PKCE 로그인을 거쳐 받은 액세스 토큰을 <code>Authorization: Bearer</code> 로 보냅니다. 토큰은 <strong>서명·발급자·만료</strong>를 검사하고 <strong>이 서버를 위해 발급된 것인지</strong>(<code>aud</code> 또는 발급 클라이언트 <code>azp</code>)를 봅니다 — 리소스 식별자(기본 <code>https://&lt;host&gt;/mcp</code>)·위 <code>Client ID</code>·허용 대상 가운데 하나여야 합니다. 실제 Keycloak 액세스 토큰은 클라이언트를 <code>azp</code> 에 담으므로, <strong>MCP 클라이언트의 Client ID 를 허용 대상에 적으면 매퍼 없이 연결</strong>되고, 규격대로 하려면 Keycloak 클라이언트에 Audience 매퍼를 더하세요. 토큰은 <strong>이미 등록된 계정</strong>만 인증하고(웹으로 먼저 한 번 로그인), 개인 키와 같은 읽기 전용 규칙을 따릅니다. 클라이언트가 동적 등록(DCR)을 쓰려면 Keycloak 의 클라이언트 등록 정책을 열어 두거나, 미리 만든 공개 클라이언트의 Client ID 를 클라이언트에 지정하세요.</p>}{group.title === 'ITSM 연동' && <p className="setting-help">업무 상황판에서 <strong>SR 번호를 입력하면 제목을 가져옵니다</strong>. 주소는 두 개이며 서로 다를 수 있습니다 — <strong>조회 주소</strong>는 서버가 제목을 물어보는 API이고, <strong>이동 주소</strong>는 사용자가 클릭했을 때 열리는 포털입니다. 이동 주소를 비우면 조회 주소를 그대로 씁니다. 두 주소 모두 <code>{'{id}'}</code> 자리에 SR 번호가 들어가며, <code>{'{id}'}</code> 가 없으면 <code>?sr_id=SR2609-00001</code> 처럼 파라미터로 붙습니다(파라미터 이름은 위에서 바꿉니다). 제목은 <strong>JSON 경로</strong>(<code>result.request.0.subject</code> 처럼 점으로 구분, 숫자는 배열 위치)로 찾고, API가 없고 HTML만 있는 시스템이라면 <strong>정규식</strong>(<code>&lt;title&gt;([^&lt;]+)</code> 처럼 괄호 하나)으로 찾습니다. 저장된 링크는 <strong>SR 번호만</strong>이므로 포털 주소가 바뀌면 이 설정만 고치면 기존 일정의 링크도 함께 옮겨집니다.</p>}{group.title === '검색' && <p className="setting-help">유사 검색은 PostgreSQL <code>pg_trgm</code>, 의미 검색은 <code>pgvector</code>와 OpenAI 호환 <code>/v1/embeddings</code> Endpoint가 필요합니다. 확장이 없으면 해당 단계는 자동으로 비활성화되고 기존 검색이 그대로 동작합니다. 코사인 점수 범위는 임베딩 모델마다 다르므로 <strong>의미 검색 최소 점수</strong>는 아래 임베딩 현황을 보며 조정하세요.</p>}{group.title.startsWith('Confluence') && <p className="setting-help">Confluence Server 6.9.1은 PAT 대신 연동 전용 Basic Auth 계정을 사용합니다. 입력한 비밀번호와 AI API Key는 암호화되어 저장되며 브라우저로 다시 전달되지 않습니다.</p>}{group.keys.map(key => { const setting = settings.find(s => s.key === key); if (!setting) return null; const isBoolean = booleanKeys.includes(key); const secretUnavailable = setting.secret && setting.configured && !setting.available; return <label className={isBoolean ? 'toggle-row' : 'setting-row'} key={key}><span><strong>{labels[key] ?? key}</strong>{setting.secret && setting.configured && <small className={secretUnavailable ? 'secret-unavailable' : ''}>{secretUnavailable ? '복호화할 수 없음 · 다시 입력 필요' : '현재 비밀값이 안전하게 설정됨'}{' '}<button type="button" className="text-button" onClick={() => clearSecret(key)}>지우기</button></small>}</span>{isBoolean ? <input type="checkbox" checked={values[key] === 'true'} onChange={e => setValues({ ...values, [key]: String(e.target.checked) })}/> : key === 'workflow.week_start' ? <select value={values[key]} onChange={e => setValues({ ...values, [key]: e.target.value })}>{weekdays.map(day => <option key={day.value} value={day.value}>{day.label}</option>)}</select> : key === 'confluence.auth_mode' ? <select value={values[key]} onChange={e => setValues({ ...values, [key]: e.target.value })}><option value="BASIC">Basic Auth</option><option value="NONE">Reverse Proxy 인증</option></select> : key === 'mail.security' ? <select value={values[key]} onChange={e => setValues({ ...values, [key]: e.target.value })}><option value="NONE">없음 (평문)</option><option value="STARTTLS">STARTTLS</option><option value="TLS">TLS</option></select> : <input type={setting.secret ? 'password' : 'text'} value={values[key]} placeholder={secretUnavailable ? '새 비밀값을 입력하세요' : setting.secret && setting.configured ? '변경할 때만 입력' : key === 'ai.endpoint' ? 'https://ai.internal/v1/chat/completions' : key === 'confluence.base_url' ? 'https://confluence.internal/confluence' : ''} onChange={e => setValues({ ...values, [key]: e.target.value })}/>}</label>})}{group.title.startsWith('AI Gateway') && <div className="inline-test"><Button variant="secondary" onClick={testAI}>AI Structured Output 연결 시험</Button></div>}{group.title.startsWith('Confluence') && <div className="inline-test"><Button variant="secondary" onClick={testConfluence}>Confluence REST 연결 시험</Button></div>}{group.title === '주간보고 메일 발송' && mailHealth && <p className="setting-help">최근 {mailHealth.days}일 · 발송 {mailHealth.sent.toLocaleString()}건 · 대기 {mailHealth.queued.toLocaleString()}건 · <strong className={mailHealth.failed > 0 ? 'danger-text' : undefined}>실패 {mailHealth.failed.toLocaleString()}건</strong> · 사용자 {mailHealth.writers.toLocaleString()}명{mailHealth.lastError && <><br/>마지막 실패 사유: <code>{mailHealth.lastError}</code></>}{mailHealth.sent === 0 && mailHealth.queued === 0 && mailHealth.failed === 0 && ' — 아직 발송한 주간보고가 없습니다. 사용자가 개인 설정에서 켜야 시작됩니다.'}</p>}{group.title === '주간보고 메일 발송' && mailDeliveries && (mailDeliveries.items.length > 0 || mailKind !== '' || mailStatus !== '') && <div className="inline-test"><label>종류 <select aria-label="발송 종류로 거르기" value={mailKind} onChange={event => setMailKind(event.target.value as MailDeliveryKind | '')}><option value="">전체</option>{(Object.keys(mailDeliveryKindLabels) as MailDeliveryKind[]).map(kind => <option key={kind} value={kind}>{mailDeliveryKindLabels[kind]}</option>)}</select></label><label>상태 <select aria-label="발송 상태로 거르기" value={mailStatus} onChange={event => setMailStatus(event.target.value as MailDeliveryStatus | '')}><option value="">전체</option>{(Object.keys(mailDeliveryStatusLabels) as MailDeliveryStatus[]).map(status => <option key={status} value={status}>{mailDeliveryStatusLabels[status]}</option>)}</select></label></div>}{group.title === '주간보고 메일 발송' && mailDeliveries && mailDeliveries.items.length === 0 && (mailKind !== '' || mailStatus !== '') && <p className="setting-help">이 조건에 맞는 발송 기록이 최근 {mailDeliveries.days}일 안에 없습니다.</p>}{group.title === '주간보고 메일 발송' && mailDeliveries && mailDeliveries.items.length > 0 && <div className="table-wrap"><table><thead><tr><th>종류</th><th>수신자</th><th>제목</th><th>상태</th><th>시도</th><th>사유</th><th>시각</th></tr></thead><tbody>{mailDeliveries.items.map((item, index) => <tr key={index}><td>{mailDeliveryKindLabels[item.kind] ?? item.kind}</td><td><strong>{item.userName}</strong><small className="cell-sub">{item.address}</small></td><td>{item.subject}</td><td className={item.status === 'FAILED' ? 'danger-text' : undefined}>{mailDeliveryStatusLabels[item.status] ?? item.status}</td><td>{item.attempts}</td><td>{item.errorMessage ? <code>{item.errorMessage}</code> : '-'}</td><td>{formatDate(item.sentAt ?? item.createdAt)}</td></tr>)}</tbody></table></div>}{group.title === '주간보고 메일 발송' && mailDeliveries?.truncated && <p className="setting-help">최근 {mailDeliveries.items.length}건만 보여 줍니다 — 이보다 오래된 발송이 최근 {mailDeliveries.days}일 안에 더 있으니 종류·상태로 좁혀 보세요.</p>}{group.title === '주간보고 메일 발송' && <div className="inline-test"><span className="muted">시험 메일은 관리자 본인의 주소로 갑니다.</span><Button variant="secondary" onClick={testMail}>메일 발송 시험</Button></div>}{group.title === 'ITSM 연동' && <div className="inline-test"><input aria-label="시험할 SR 번호" value={itsmSample} placeholder="SR2609-00001" onChange={event => setItsmSample(event.target.value)}/><Button variant="secondary" onClick={testITSM}>SR 조회 시험</Button></div>}{group.title === '검색' && <div className="inline-test">{embedding && <span className="muted">{!embedding.vectorAvailable ? 'pgvector 미설치 · 의미 검색 비활성' : embedding.countsUnread ? `pgvector 사용 가능 · 임베딩 현황을 읽지 못했습니다 — 0건이 아니라 집계에 실패한 것입니다${embedding.reason ? ` · ${embedding.reason}` : ''}` : `pgvector 사용 가능 · 임베딩 ${embedding.embedded}/${embedding.items}건${embedding.stale > 0 ? ` · 수정 후 갱신 대기 ${embedding.stale}건` : ''}${embedding.reason ? ` · ${embedding.reason}` : ''}`}</span>}<Button variant="secondary" onClick={rebuildEmbeddings}>임베딩 다시 생성</Button></div>}</Card>)}<div className="admin-actions"><Button variant="secondary" onClick={testOIDC}>OIDC 연결 시험</Button><Button onClick={() => save()}>설정 저장</Button></div></div>
}

function ConfluenceTab({ notify }: { notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [status, setStatus] = useState<ConfluenceSyncStatus>(); const [mappings, setMappings] = useState<ConfluenceMapping[]>(); const [values, setValues] = useState<Record<number,string>>({}); const [actives,setActives]=useState<Record<number,boolean>>({}); const [failure,setFailure]=useState('')
  // The status query refuses the card when one of its reads fails, rather than
  // answering with the zero it would otherwise be left holding. That refusal
  // used to land here as a spinner that turned forever and said nothing.
  const load = async () => { setFailure(''); try { const [nextStatus,nextMappings] = await Promise.all([api<ConfluenceSyncStatus>('/api/v1/admin/confluence/sync/status'),api<ConfluenceMapping[]>('/api/v1/admin/confluence/users/mappings')]); setStatus(nextStatus);setMappings(nextMappings);setValues(Object.fromEntries(nextMappings.map(item=>[item.userId,item.externalUsername??item.suggestedUsername])));setActives(Object.fromEntries(nextMappings.map(item=>[item.userId,item.active??true]))) } catch (error) { setFailure(errorText(error, 'Confluence 자동 수집 상태를 조회할 수 없습니다.')) } }
  useEffect(()=>{load();const timer=window.setInterval(()=>api<ConfluenceSyncStatus>('/api/v1/admin/confluence/sync/status').then(setStatus).catch(()=>undefined),10000);return()=>window.clearInterval(timer)},[])
  const sync=async()=>{try{await post('/api/v1/admin/confluence/sync');notify('Confluence 증분 동기화를 요청했습니다.');setTimeout(load,800)}catch(error){notify(error instanceof Error?error.message:'동기화를 요청할 수 없습니다.','error')}}
  const test=async()=>{try{await post('/api/v1/admin/settings/confluence/test');notify('Confluence REST 연결에 성공했습니다.')}catch(error){notify(error instanceof Error?error.message:'연결에 실패했습니다.','error')}}
  const save=async(item:ConfluenceMapping)=>{try{await put(`/api/v1/admin/confluence/users/${item.userId}/mapping`,{externalUsername:values[item.userId],active:actives[item.userId]});await load();notify(`${item.displayName} 사용자 매핑을 저장했습니다.`)}catch(error){notify(error instanceof Error?error.message:'매핑을 저장할 수 없습니다.','error')}}
  if(failure)return <Card title="자동 수집 상태"><Empty>{failure}</Empty><div className="admin-actions"><Button variant="secondary" onClick={()=>void load()}>다시 시도</Button></div></Card>
  if(!status||!mappings)return <Spinner/>;return <><Card title="자동 수집 상태" action={<span className={`sync-chip ${status.status.toLowerCase()}`}>{status.status}</span>}><div className="sync-overview"><div><small>최근 성공</small><strong>{formatDate(status.lastSuccessAt)}</strong></div><div><small>조회 / 변경</small><strong>{status.pagesScanned} / {status.pagesChanged}</strong></div><div><small>새 초안</small><strong>{status.candidatesCreated}</strong></div><div><small>실패</small><strong>{status.pagesFailed}</strong></div><div><small>매핑 / 미매핑</small><strong>{status.mappedUsers} / {status.unmappedUsers}</strong></div></div>{status.unresolvedActors>0&&<div className="sync-unattributed">Weekly 계정에 연결되지 않은 Confluence 사용자 {status.unresolvedActors}명 때문에 페이지 {status.unattributedPages}개가 초안이 되지 못했습니다. 아래 진단에서 아이디를 확인해 매핑하세요.</div>}{status.errorMessage&&<div className="import-error">{status.errorMessage}</div>}<div className="admin-actions"><Button variant="secondary" onClick={test}>연결 시험</Button><Button onClick={sync} disabled={!status.enabled||status.status==='RUNNING'}>{status.status==='RUNNING'?'동기화 중…':'지금 증분 동기화'}</Button></div></Card><Card title="Weekly ↔ Confluence 사용자 매핑"><p className="muted"><b>명시 매핑 → 이메일 @ 앞부분 → 로그인 아이디</b> 순서로 자동 연결합니다. 예: <code>hong@example.com → hong</code>. 자동 판정이 유일하지 않은 사용자만 직접 지정하세요.</p><div className="table-wrap"><table><thead><tr><th>Weekly 사용자</th><th>Keycloak 이메일</th><th>Confluence 아이디</th><th>활성</th><th>매핑 근거</th><th/></tr></thead><tbody>{mappings.map(item=><tr key={item.userId}><td><strong>{item.displayName}</strong><small className="cell-sub">{item.username}</small></td><td>{item.email||'-'}</td><td><input value={values[item.userId]??''} onChange={e=>setValues({...values,[item.userId]:e.target.value})}/></td><td><input type="checkbox" checked={actives[item.userId]??true} onChange={e=>setActives({...actives,[item.userId]:e.target.checked})}/></td><td>{item.mappingSource??`추천: ${item.suggestionSource}`}</td><td><Button variant="secondary" onClick={(